                        }),
                    );

                    if (rest.prepaidCredit) {
                        if (/^[ \t]*[0-9]+\.?[0-9]+[ \t]*(\$|usd|USD)?$/.test(rest.prepaidCredit)) {
                            rest.prepaidCredit = rest.prepaidCredit.match(/[0-9]+\.?[0-9]+/)[0];
