topup = '''
/**
 * A prepaid credit, or "top up", offering. Customers on a top up offering pre pay for their usage which is held
 * as a credit balance on their wallet. Every hour the usage which the customer has accrued is deducted from their
 * wallet and, if the balance of the wallet falls below `topUpThreshold * topUpAmount`, the wallet is topped back up
 * to the `topUpAmount` via an invoice whose payment is stored on the wallet as credit.
 */
export class TopUp extends UsageBased {
    static readonly logger = new Logger(TopUp.name);

    static roundToCents(amount: number): number {
        return Math.round(amount * 100) / 100;
    }

    /**
     * The amount which the customer wallet is topped up to.
     */
    public getTopUpAmount(): number {
        const topUpAmount = parseFloat(this.topUpAmount);
        return isNaN(topUpAmount) ? 0 : topUpAmount;
    }

    /**
     * The percentage of the top up amount which the wallet balance must fall below in order to be topped up.
     */
    public getTopUpThreshold(): number {
        const topUpThreshold = parseFloat(
            this.topUpThreshold === undefined || this.topUpThreshold === null
                ? DEFAULT_TOP_UP_THRESHOLD
                : this.topUpThreshold,
        );
        return isNaN(topUpThreshold) ? parseFloat(DEFAULT_TOP_UP_THRESHOLD) : topUpThreshold;
    }

    /**
     * The wallet balance which triggers a top up. Whenever the balance of the wallet is below this value the
     * wallet is topped back up to the top up amount.
     */
    public getTopUpThresholdBalance(): number {
        return TopUp.roundToCents(this.getTopUpAmount() * this.getTopUpThreshold());
    }

    /**
     * The current balance of the customer wallet.
     */
    public async getWalletBalance(): Promise<number> {
        const { balance } = await this.creditService.findCreditBalance({
            businessID: this.businessID,
            customerId: this.customerId,
        });
        const walletBalance = parseFloat(balance);
        return isNaN(walletBalance) ? 0 : walletBalance;
    }

    async enroll(subject: string, customer?: ReadCustomerResponseData): Promise<void> {
        TopUp.logger.log(
            `Enrolling customer ${this.customerId} in top up offering ${this.offeringName}. Top up amount: ${this.topUpAmount}, top up threshold: ${this.topUpThreshold}`,
        );
        await this.registerBillingSchedule(subject);
        await this.topUpWallet(customer);
    }

    /**
     * Tops the customer wallet back up to the `topUpAmount` when the wallet balance has fallen below
     * `topUpThreshold * topUpAmount`. The exact difference between the current balance and the `topUpAmount`
     * is charged with an invoice, the payment of that invoice is stored on the wallet as credit.
     */
    public async topUpWallet(customer?: ReadCustomerResponseData): Promise<string | undefined> {
        const topUpAmount = this.getTopUpAmount();
        if (!topUpAmount) {
            TopUp.logger.warn(
                `No top up amount configured for offering ${this.offeringId}, skipping the top up of the wallet for customer ${this.customerId}`,
            );
            return;
        }
        if (!this.creditService) {
            AuditService.publishEvent({
                message: 'No credit service available to top up the customer wallet',
                topic: AuditScope.ERROR,
                data: [{ customerId: this.customerId, businessID: this.businessID, offeringId: this.offeringId }],
            });
            return;
        }
        const walletBalance = await this.getWalletBalance();
        const topUpThresholdBalance = this.getTopUpThresholdBalance();
        if (walletBalance >= topUpThresholdBalance) {
            TopUp.logger.log(
                `Wallet balance of ${walletBalance} for customer ${this.customerId} is not below the top up threshold balance of ${topUpThresholdBalance}. No top up required.`,
            );
            return;
        }
        const amountDue = TopUp.roundToCents(topUpAmount - walletBalance);
        if (amountDue <= 0) {
            return;
        }
        TopUp.logger.log(
            `Wallet balance of ${walletBalance} for customer ${this.customerId} is below the top up threshold balance of ${topUpThresholdBalance}. Charging ${amountDue} to top the wallet up to ${topUpAmount}.`,
        );
        const lineItems = new InvoiceLineItems();
        lineItems.addLineItem(new InvoiceLineItem(`${this.offeringName} (Top Up)`, 1, amountDue, 'Top Up'));
        const { invoiceId } = await this.invoicesService.create({
            businessID: this.businessID,
            customer,
            customerId: this.customerId,
            items: lineItems,
            invoiceDate: new Date().toISOString(),
            currency: Offering.getCurrency({ customer, offering: this }),
            paymentAsCredit: true,
        });
        return invoiceId;
    }

    /**
     * Deducts the usage accrued for the given time range from the customer wallet. The usage is always deducted,
     * even when the usage is greater than the current balance of the wallet. Usage is never invoiced separately
     * for top up offerings, the customer pays for their usage upfront when their wallet is topped up.
     */
    public async deductUsageFromWallet({
        startDate,
        endDate,
        customer,
    }: {
        startDate: Date;
        endDate: Date;
        customer?: ReadCustomerResponseData;
    }): Promise<number> {
        const lineItems = new InvoiceLineItems();
        await Offering.getLineItemsForUsage({
            startDate,
            endDate,
            customer,
            lineItems,
            negative: false,
            businessID: this.businessID,
            customerId: this.customerId,
            customerService: this.customerService,
            offeringInstance: this,
            dimensions: this.dimensions,
        });
        if (this?.discount?.name) {
            if (!this.discount.endDate || !DatetimeUtils.isDateInPast(new Date(this.discount.endDate))) {
                Offering.addDiscountLineItem(this.discount, lineItems);
            }
        }
        const usageTotal = TopUp.roundToCents(lineItems.getTotal());
        if (usageTotal <= 0) {
            TopUp.logger.log(
                `No usage to deduct from the wallet of customer ${this.customerId} between ${startDate?.toISOString()} and ${endDate?.toISOString()}`,
            );
            return 0;
        }
        TopUp.logger.log(
            `Deducting ${usageTotal} of usage from the wallet of customer ${this.customerId} between ${startDate?.toISOString()} and ${endDate?.toISOString()}`,
        );
        // The usage is always deducted from the wallet, even when the usage exceeds the current wallet balance.
        await this.creditService.create(
            {
                businessID: this.businessID,
                customerId: this.customerId,
                transactionAmount: (usageTotal * -1).toFixed(2),
                timestamp: new Date().toISOString(),
                metadata: {
                    offeringId: this.offeringId,
                    reason: `Usage for ${this.offeringName}`,
                },
            },
            false,
            true,
        );
        return usageTotal;
    }

    /**
     * Runs every hour for a customer enrolled in a top up offering. The usage accrued in the last hour is deducted
     * from the customer wallet, no usage invoice is generated. Once the usage has been deducted the wallet is
     * topped back up if the updated balance has fallen below the top up threshold.
     */
    async processBilling(
        startDateOverride?: Date,
        endDateOveride?: Date,
        customer?: ReadCustomerResponseData,
    ): Promise<string> {
        const { startTime, endTime } = Billing.billingCycleToTimeRange(this.billingCycle);
        const startDate = startDateOverride ? startDateOverride : new Date(startTime);
        const endDate = endDateOveride ? endDateOveride : new Date(endTime);
        await this.deductUsageFromWallet({ startDate, endDate, customer });
        // The refill is always evaluated with the balance of the wallet after the usage has been deducted
        return this.topUpWallet(customer);
    }

    async unenroll({ customer }: { customer?: ReadCustomerResponseData }): Promise<void> {
        TopUp.logger.log(`Unenrolling customer ${this.customerId} from top up offering ${this.offeringName}`);
        const { startTime } = Billing.billingCycleToTimeRange(this.billingCycle);
        // Deduct any usage which has been accrued since the last hourly check, no invoice is generated for usage
        await this.deductUsageFromWallet({ startDate: new Date(startTime), endDate: new Date(), customer });
        await this.deregisterBillingSchedule();
    }
}
