import { DEFAULT_TOP_UP_THRESHOLD, ValidBillingCycles } from '../dto/createOffering.dto.js';
import { ReadOfferingResponseData } from '../dto/readOffering.dto.js';
import { SupportedCurrencies } from '../dto/SupportedCurrencies.js';
import { MILLISECONDS_IN_AN_HOUR, Offering, OfferingPackageEntity, TopUp } from './offeringPackage.entity.js';
import { OfferingType } from './OfferingType.js';

describe('TopUp Offering', () => {
    const fakeBusinessID = 'fakeBusinessID';
    const fakeCustomerID = 'fakeCustomerID';
    const fakeSettings = { freeDimensionOnInvoice: FreeDimensionOnInvoice.show } as ReadSettingsResponseData;
    const fakeCustomer = {
        customerId: fakeCustomerID,
        customerName: 'fakeCustomerName',
        paymentChannel: paymentChannel.manual,
        businessID: fakeBusinessID,
        currency: SupportedCurrencies.USD,
        email: 'fakeEmail',
    } as ReadCustomerResponseData;

    let invoicesService: InvoicesService;
    let schedulerService: SchedulerService;
    let customerService: CustomerService;
    let creditService: CreditService;
    let invoiceCreateMock: jest.Mock;
    let schedulerCreateMock: jest.Mock;
    let schedulerRemoveMock: jest.Mock;
    let creditCreateMock: jest.Mock;
    let findCreditBalanceMock: jest.Mock;
    let findUsageForCustomerMock: jest.Mock;

    const topUpOfferingConfig = (
        overrides: Partial<ReadOfferingResponseData> = {},
    ): ReadOfferingResponseData => ({
        offeringId: 'topUpOfferingId',
        offeringName: 'Pay As You Go',
        offeringType: OfferingType.usageBased,
        currency: SupportedCurrencies.USD,
        billingCycle: ValidBillingCycles.topUp,
        topUpAmount: '100',
        topUpThreshold: '0.2',
        dimensions: [
            {
                dimensionId: 'dimensionId',
                dimensionName: 'API Calls',
                aggregationInterval: aggregationInterval.day,
                aggregationMethod: aggregationMethod.sum,
                consumptionPrice: '2',
                usageIncrement: '1',
                rounding: roundingEnum.ceiling,
                consumptionUnit: { unit: countBasedUnits['count-based'], type: 'count' },
            },
        ],
        ...overrides,
    });

    const getTopUpInstance = (overrides: Partial<ReadOfferingResponseData> = {}): TopUp =>
        Offering.getInstance(
            topUpOfferingConfig(overrides),
            fakeCustomerID,
            fakeBusinessID,
            invoicesService,
            fakeSettings,
            schedulerService,
            customerService,
            undefined,
            undefined,
            creditService,
        ) as TopUp;

    const setWalletBalance = (...balances: string[]) => {
        balances.forEach((balance) => findCreditBalanceMock.mockResolvedValueOnce({ balance }));
    };

    const setUsage = (value: string) => {
        findUsageForCustomerMock.mockResolvedValue({
            message: 'fake',
            data: [{ dimensionId: 'dimensionId', usage: [{ value }] }],
        });
    };

    beforeEach(() => {
        invoiceCreateMock = jest.fn(async () => ({ invoiceId: 'topUpInvoiceId', message: 'Generated invoice' }));
        schedulerCreateMock = jest.fn(async () => ({ message: 'Cron expression added', data: [] }));
        schedulerRemoveMock = jest.fn(async () => ({ message: 'Deleted Schedule', data: [] }));
        creditCreateMock = jest.fn(async () => ({ message: 'ok', transactionRow: {} }));
        findCreditBalanceMock = jest.fn(async () => ({ balance: '0' }));
        findUsageForCustomerMock = jest.fn(async () => ({ message: 'fake', data: [] }));
        invoicesService = { create: invoiceCreateMock } as unknown as InvoicesService;
        schedulerService = {
            create: schedulerCreateMock,
            remove: schedulerRemoveMock,
        } as unknown as SchedulerService;
        customerService = { findUsageForCustomer: findUsageForCustomerMock } as unknown as CustomerService;
        creditService = {
            create: creditCreateMock,
            findCreditBalance: findCreditBalanceMock,
        } as unknown as CreditService;
    });

    describe('configuration', () => {
        it('should create a TopUp instance for usage based offerings with a topUp billing cycle', () => {
            const offering = getTopUpInstance();
            expect(offering).toBeInstanceOf(TopUp);
            expect(offering.topUpAmount).toEqual('100');
            expect(offering.topUpThreshold).toEqual('0.2');
        });

        it('should default the top up threshold to 0.2', () => {
            const offering = getTopUpInstance({ topUpThreshold: undefined });
            expect(offering.topUpThreshold).toEqual(DEFAULT_TOP_UP_THRESHOLD);
            expect(offering.getTopUpThresholdBalance()).toEqual(20);
        });

        it('should default the top up threshold to 0.2 on the offering entity', () => {
            const entity = new OfferingPackageEntity({
                offeringName: 'Pay As You Go',
                businessID: fakeBusinessID,
                offeringId: 'topUpOfferingId',
                billingCycle: ValidBillingCycles.topUp,
                topUpAmount: '50',
            } as OfferingPackageEntity);
            expect(entity.topUpAmount).toEqual('50');
            expect(entity.topUpThreshold).toEqual('0.2');
        });

        it('should register an hourly scheduler for top up offerings', () => {
            expect(getTopUpInstance().getCronRate()).toEqual(SupportedMeasurementFrequencies.everyHour);
        });

        it('should calculate the time range for a top up billing cycle as the last hour', () => {
            const { startTime, endTime } = Billing.billingCycleToTimeRange(ValidBillingCycles.topUp);
            expect(new Date(endTime).getTime() - new Date(startTime).getTime()).toEqual(MILLISECONDS_IN_AN_HOUR);
        });
    });

    describe('enrollment', () => {
        it('should create an hourly billing schedule and top the wallet up to the top up amount', async () => {
            setWalletBalance('0');
            const offering = getTopUpInstance();
            await offering.enroll('fakeSubject', fakeCustomer);

            expect(schedulerCreateMock).toHaveBeenCalledTimes(1);
            expect(schedulerCreateMock.mock.calls[0][0]).toEqual(
                expect.objectContaining({ rate: SupportedMeasurementFrequencies.everyHour }),
            );
            expect(invoiceCreateMock).toHaveBeenCalledTimes(1);
            const [invoiceInput] = invoiceCreateMock.mock.calls[0];
            expect(invoiceInput).toEqual(expect.objectContaining({ paymentAsCredit: true }));
            expect(invoiceInput.items.getTotal()).toEqual(100);
        });

        it('should only charge the difference between the wallet balance and the top up amount', async () => {
            setWalletBalance('12.50');
            const offering = getTopUpInstance();
            await offering.enroll('fakeSubject', fakeCustomer);

            expect(invoiceCreateMock).toHaveBeenCalledTimes(1);
            expect(invoiceCreateMock.mock.calls[0][0].items.getTotal()).toEqual(87.5);
        });

        it('should not top the wallet up when the balance is not below the threshold', async () => {
            setWalletBalance('20');
            const offering = getTopUpInstance();
            await offering.enroll('fakeSubject', fakeCustomer);

            expect(schedulerCreateMock).toHaveBeenCalledTimes(1);
            expect(invoiceCreateMock).not.toHaveBeenCalled();
        });
    });

    describe('hourly processing', () => {
        it('should deduct the usage from the wallet without generating a usage invoice', async () => {
            setUsage('10');
            // 20 of usage leaves a balance of 80 which is above the threshold balance of 20
            setWalletBalance('100', '80');
            const offering = getTopUpInstance();
            await offering.processBilling(undefined, undefined, fakeCustomer);

            expect(creditCreateMock).toHaveBeenCalledTimes(1);
            expect(creditCreateMock.mock.calls[0][0]).toEqual(
                expect.objectContaining({
                    businessID: fakeBusinessID,
                    customerId: fakeCustomerID,
                    transactionAmount: '-20.00',
                }),
            );
            expect(invoiceCreateMock).not.toHaveBeenCalled();
        });

        it('should top the wallet up using the balance after the usage was deducted', async () => {
            setUsage('45');
            // 90 of usage leaves a balance of 10 which is below the threshold balance of 20
            setWalletBalance('100', '10');
            const offering = getTopUpInstance();
            const invoiceId = await offering.processBilling(undefined, undefined, fakeCustomer);

            expect(creditCreateMock.mock.calls[0][0]).toEqual(
                expect.objectContaining({ transactionAmount: '-90.00' }),
            );
            expect(invoiceCreateMock).toHaveBeenCalledTimes(1);
            expect(invoiceCreateMock.mock.calls[0][0].items.getTotal()).toEqual(90);
            expect(invoiceId).toEqual('topUpInvoiceId');
        });

        it('should deduct usage which exceeds the wallet balance and charge the gap to the top up amount', async () => {
            setUsage('30');
            // 60 of usage against a balance of 10 leaves the wallet with -50
            setWalletBalance('10', '-50');
            const offering = getTopUpInstance();
            await offering.processBilling(undefined, undefined, fakeCustomer);

            expect(creditCreateMock).toHaveBeenCalledTimes(1);
            const [creditInput, validateCustomer, allowNegativeBalance] = creditCreateMock.mock.calls[0];
            expect(creditInput).toEqual(expect.objectContaining({ transactionAmount: '-60.00' }));
            expect(validateCustomer).toEqual(false);
            expect(allowNegativeBalance).toEqual(true);
            expect(invoiceCreateMock.mock.calls[0][0].items.getTotal()).toEqual(150);
        });

        it('should not create any wallet transaction when there is no usage', async () => {
            setWalletBalance('100');
            const offering = getTopUpInstance();
            await offering.processBilling(undefined, undefined, fakeCustomer);

            expect(creditCreateMock).not.toHaveBeenCalled();
            expect(invoiceCreateMock).not.toHaveBeenCalled();
        });
    });

    describe('unenrollment', () => {
        it('should remove the hourly schedule without generating an invoice', async () => {
            const offering = getTopUpInstance();
            await offering.unenroll({ customer: fakeCustomer });

            expect(schedulerRemoveMock).toHaveBeenCalled();
            expect(invoiceCreateMock).not.toHaveBeenCalled();
        });
    });
});

